				v := i*m + (j+1)
				adj[u] = append(adj[u], v)
			}
		}
	}
	// Hopcroft-Karp or Hungarian for maximum bipartite matching
	// Since total <= 40, use simple Kuhn's algorithm
	matchR := make([]int, total)
	for i := range matchR {
		matchR[i] = -1
	}
	result := 0
	for u := 0; u < total; u++ {
