func tryKuhn(u int, adj [][]int, visited []bool, matchR []int) bool {
	for _, v := range adj[u] {
		if !visited[v] {
			visited[v] = true
			if matchR[v] == -1 || tryKuhn(matchR[v], adj, visited, matchR) {
				matchR[v] = u
				return true
			}
		}
	}
	return false
