		return
	}
	// Maximum number of spiders that can be moved to a single cell is total.
	// So minimum occupied cells is ceil(total / total) = 1.
	// But we need to check if it's possible to move all spiders to one cell.
	// For a grid, it's possible if there exists a cell reachable by all spiders in one move.
	// The center cell (or any cell) can be reached by all spiders if the grid is connected.
	// Since all cells are connected, we can move all spiders to one cell.
	// Thus, the maximum free cells is total - 1.
	// However, the sample input 2x3 gives 4, which is 6-2=4. So the above logic is wrong.
	// The correct approach is to find the maximum number of spiders that can be moved to a single cell.
	// For each cell, count how many spiders can reach it in one move.
	// The answer is total - max(count).
	maxCount := 0
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			count := 0
			for x := 0; x < n; x++ {
				for y := 0; y < m; y++ {
					if canReach(x, y, i, j, n, m) {
						count++
					}
				}
			}
			if count > maxCount {
				maxCount = count
			}
		}
	}
	fmt.Println(total - maxCount)
}

func canReach(x, y, tx, ty, n, m int) bool {
	// Spider at (x,y) can move to (tx,ty) if they are the same or adjacent
	dx := abs(x - tx)
	dy := abs(y - ty)
	return dx+dy <= 1
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
